import path from "node:path";

const SHOT = (page, outDir, name) =>
  page.screenshot({ path: path.join(outDir, `${name}.png`) });

const runCommand = async (page, command) => {
  await page.keyboard.press("Escape").catch(() => {});
  await page.waitForTimeout(300);
  await page.click("body", { position: { x: 700, y: 400 } }).catch(() => {});
  await page.keyboard.press("Meta+p");
  await page.waitForTimeout(600);
  await page.keyboard.type(command, { delay: 20 });
  await page.waitForTimeout(900);
  await page.keyboard.press("Enter");
  await page.waitForTimeout(2000);
};

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamjs?.extension?.queryBuilder));
  },

  async run({ page, outDir }) {
    const proof = {};

    await runCommand(page, "DG: Export - Discourse graph");
    const dlg = page.locator(".bp3-dialog").first();
    await dlg.waitFor({ timeout: 25000 });
    await page.waitForTimeout(800);

    const toggle = dlg.getByText("Export options").first();
    if (await toggle.count()) {
      await toggle.click().catch(() => {});
      await page.waitForTimeout(1200);
    }
    await SHOT(page, outDir, "export-01-options-open");

    proof.switches = await dlg.locator(".bp3-switch").count();
    proof.checkboxes = await dlg.locator(".bp3-checkbox").count();
    proof.fullText = await dlg.innerText();

    // Is the last option's description actually rendered and reachable?
    proof.lastDescriptionComplete = proof.fullText.includes("content tree.");

    // Measure whether the dialog clips its own content.
    proof.overflow = await dlg.evaluate((el) => {
      const body = el.querySelector(".bp3-dialog-body") || el;
      const cs = getComputedStyle(body);
      return {
        scrollHeight: body.scrollHeight,
        clientHeight: body.clientHeight,
        overflowY: cs.overflowY,
        clipped: body.scrollHeight > body.clientHeight + 2,
      };
    });

    if (proof.overflow.clipped) {
      await dlg.evaluate((el) => {
        const body = el.querySelector(".bp3-dialog-body") || el;
        body.scrollTop = body.scrollHeight;
      });
      await page.waitForTimeout(700);
      await SHOT(page, outDir, "export-02-options-scrolled");
    }

    return proof;
  },

  async cleanup({ page }) {
    await page.keyboard.press("Escape").catch(() => {});
  },
};

