// PR 1525: does navigating node A -> node B via settings search carry A's form state into B?
import path from "node:path";

const SHOT = (page, outDir, name) =>
  page.screenshot({ path: path.join(outDir, `${name}.png`) });

const runCommand = async (page, command) => {
  await page.keyboard.press("Escape").catch(() => {});
  await page.waitForTimeout(300);
  await page.click("body", { position: { x: 700, y: 400 } }).catch(() => {});
  await page.keyboard.press("Meta+p");
  await page.waitForTimeout(600);
  await page.keyboard.type(command, { delay: 20 });
  await page.waitForTimeout(900);
  await page.keyboard.press("Enter");
  await page.waitForTimeout(1800);
};

// The Tag row's input, read straight from the DOM.
const readTagInput = (page) =>
  page.evaluate(() => {
    const row = Array.from(
      document.querySelectorAll(".dg-settings-node-config [data-setting-id]"),
    ).find((el) => /(^|\s)Tag(\s|$)/.test(el.textContent || ""));
    const input = row?.querySelector("input");
    return {
      found: Boolean(input),
      value: input ? input.value : null,
      placeholder: input ? input.placeholder : null,
    };
  });

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamjs?.extension?.queryBuilder));
  },

  async run({ page, outDir }) {
    const proof = {};

    // Ground truth: the stored tag of every node type.
    proof.storedTags = await page.evaluate(() => {
      const nodes = window.roamjs.extension.queryBuilder.getDiscourseNodes();
      return nodes
        .map((n) => ({ text: n.text, type: n.type, tag: n.tag || "" }))
        .filter((n) => n.tag)
        .slice(0, 12);
    });

    await runCommand(page, "DG: Open - Discourse settings");
    const panel = page.locator(".dg-settings-tabs").first();
    await panel.waitFor({ timeout: 25000 });
    await page.waitForTimeout(800);

    // Pick two node types that both have a stored tag and differ.
    const pair = proof.storedTags.filter(
      (n, i, a) => a.findIndex((x) => x.tag === n.tag) === i,
    );
    if (pair.length < 2) {
      proof.skipped = "need two node types with distinct stored tags";
      return proof;
    }
    const [A, B] = pair;
    proof.nodeA = A;
    proof.nodeB = B;

    const search = page
      .locator(".bp3-dialog input[placeholder*='earch'], .bp3-dialog input[type='search']")
      .first();

    // Land on node A's config page via search.
    await search.click();
    await search.fill(`${A.text} Tag`);
    await page.waitForTimeout(1300);
    await page.keyboard.press("Enter");
    await page.waitForTimeout(1600);
    proof.onA = await readTagInput(page);
    await SHOT(page, outDir, "carry-01-node-a");

    // Now jump straight to node B's Tag WITHOUT going back to the node list.
    await search.click();
    await search.fill(`${B.text} Tag`);
    await page.waitForTimeout(1300);
    await page.keyboard.press("Enter");
    await page.waitForTimeout(1600);
    proof.onB = await readTagInput(page);
    await SHOT(page, outDir, "carry-02-node-b");

    proof.breadcrumb = await page
      .locator(".dg-settings-tabs")
      .first()
      .innerText()
      .then((t) => t.slice(0, 200));

    // The bug: B's page shows A's tag instead of B's.
    proof.showsStaleValue =
      proof.onB.value === proof.onA.value && proof.onA.value !== B.tag;
    proof.expectedOnB = B.tag;

    return proof;
  },

  async cleanup({ page }) {
    await page.keyboard.press("Escape").catch(() => {});
  },
};

