      window.roamjs.extension.queryBuilder
        .getDiscourseNodes()
        .map((n) => ({ text: n.text, type: n.type, tag: n.tag || "" }))
        .filter((n) => n.tag),
    );

    await runCommand(page, "DG: Open - Discourse settings");
    const panel = page.locator(".dg-settings-tabs").first();
    await panel.waitFor({ timeout: 25000 });
    await page.waitForTimeout(800);

    const seen = new Set();
    const pair = proof.storedTags.filter((n) => {
      if (seen.has(n.tag)) return false;
      seen.add(n.tag);
      return true;
    });
    const [A, B] = pair;
    proof.nodeA = A;
    proof.nodeB = B;

    // Navigate by clicking the node row in Grammar > Nodes, then switch via search.
    await panel.getByText("Nodes", { exact: true }).first().click().catch(() => {});
    await page.waitForTimeout(1000);
    const rowA = panel.getByText(A.text, { exact: true }).first();
    await rowA.click().catch(() => {});
    await page.waitForTimeout(1500);
    proof.onA = await readInputs(page);
    await SHOT(page, outDir, "carry-01-node-a");

    // Jump straight to node B's page via the search field, without going back.
    const search = page
      .locator(".bp3-dialog input[placeholder*='earch'], .bp3-dialog input[type='search']")
      .first();
    await search.click();
    await search.fill(`${B.text} Tag`);
    await page.waitForTimeout(1400);
    const option = page.locator(".bp3-menu-item, [role='option']").first();
    if (await option.count()) {
      await option.click().catch(() => {});
    } else {
      await page.keyboard.press("Enter");
    }
    await page.waitForTimeout(1800);
    proof.onB = await readInputs(page);
    await SHOT(page, outDir, "carry-02-node-b");

    return proof;
  },

  async cleanup({ page }) {
    await page.keyboard.press("Escape").catch(() => {});
  },
};

